import type { ReactNode } from "react";
import damasceneTile from "../assets/damascene-tile.svg";

type Props = {
  /** Left side of the header (e.g. a label or a back link). */
  headerStart: ReactNode;
  /** Right side of the header. */
  headerEnd?: ReactNode;
  children: ReactNode;
  footer?: ReactNode;
};

/**
 * Fixed Damascene star-pattern backdrop (generated by `npm run pattern`).
 * The tile is W × W√3; sizes are rounded to whole pixels so it repeats without seams.
 * A radial mask softens the pattern behind the middle of the screen, where content sits.
 */
const backdropMask =
  "radial-gradient(ellipse 75% 65% at 50% 45%, rgb(0 0 0 / 0.4), #000 100%)";

/** Shared page chrome: star-pattern backdrop, top bar, optional footer. */
export function SiteLayout({ headerStart, headerEnd, children, footer }: Props) {
  return (
    <div className="min-h-screen overflow-x-hidden">
      <div
        aria-hidden
        className="fixed inset-0 pointer-events-none opacity-[0.16] bg-[position:center_top] bg-[length:160px_277px] sm:bg-[length:220px_381px]"
        style={{
          backgroundImage: `url("${damasceneTile}")`,
          maskImage: backdropMask,
          WebkitMaskImage: backdropMask,
        }}
      />
      <header className="relative z-10 flex items-center justify-between gap-4 px-6 sm:px-8 py-6 border-b border-paper/10">
        {headerStart}
        {headerEnd}
      </header>
      {children}
      {footer && (
        <footer className="relative z-10 px-6 sm:px-8 py-8 border-t border-paper/10 flex items-center justify-between gap-4 mt-16">
          {footer}
        </footer>
      )}
    </div>
  );
}

export function HomeLink({ label = "← Home" }: { label?: string }) {
  return (
    <a
      href="/"
      className="text-xs tracking-[0.3em] uppercase text-paper/40 hover:text-gold transition-colors duration-300"
    >
      {label}
    </a>
  );
}

export function Overline({ children, center = false }: { children: ReactNode; center?: boolean }) {
  return (
    <div className={`flex items-center gap-4 ${center ? "justify-center text-center" : ""}`}>
      {/* Centred: the rules only show when there's room, so a wrapped label isn't squeezed. */}
      <div className={`h-px w-12 bg-gold shrink-0 ${center ? "hidden sm:block" : ""}`} />
      <span className="text-xs tracking-[0.4em] uppercase text-gold">
        {children}
      </span>
      {center && <div className="h-px w-12 bg-gold shrink-0 hidden sm:block" />}
    </div>
  );
}

export function SectionDivider({ label }: { label: string }) {
  return (
    <div className="flex items-center gap-6">
      <div className="h-px flex-1 bg-paper/10" />
      <span className="text-xs tracking-[0.3em] uppercase text-paper/20">
        {label}
      </span>
      <div className="h-px flex-1 bg-paper/10" />
    </div>
  );
}
